import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"1、【乾】 乾下乾上","description":"周易口诀义 - 1、【乾】 乾下乾上","frontmatter":{"title":"1、【乾】 乾下乾上","description":"周易口诀义 - 1、【乾】 乾下乾上"},"headers":[],"relativePath":"zh/classics/koujueyi/003.md","filePath":"zh/classics/koujueyi/003.md"}'),r={name:"zh/classics/koujueyi/003.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_1、【乾】-乾下乾上" tabindex="-1">1、【乾】 乾下乾上 <a class="header-anchor" href="#_1、【乾】-乾下乾上" aria-label="Permalink to “1、【乾】 乾下乾上”">​</a></h1><p>引读</p><p>周易传为上经第一者，先儒云：「易有三名，夏曰连山，殷曰归藏，周曰周易。」康成云：「连山者，象山之出云；归藏者，莫不归藏于其中；周易者，言易道周普，无所不备。」窃谓易者，是文王所演，因代为名，故称周也。易取变通为义，上经者，三十卦，象阳，取其三之奇数也。经犹径也，谓圣人亦以易道教人，可以践履济涉径路，无所不通也。卦者，挂也，谓悬挂物象，吉凶之理显焉。传者，传也，如孔氏传之类也。</p><p>初九：潜龙勿用。</p><p>九二：见龙在田，利见大人。</p><p>九三：君子终日乾乾，夕惕若。厉，无咎。</p><p>九四：或跃在渊，无咎。</p><p>九五：飞龙在天，利见大人。</p><p>上九：亢龙，有悔。</p><p>用九：见群龙无首，吉。</p><p>彖曰：大哉乾元，万物资始，乃统天。云行雨施，品物流形。大明终始，六位时成，时乘六龙以御天。乾道变化，各正性命，保合太和，乃利贞。首出庶物，万国咸宁。</p><p>象曰：天行健，君子以自强不息。「潜龙勿用」，阳在下也。</p><p>「见龙在田」，德施普也。</p><p>「终日乾乾」，反复道也。</p><p>「或跃在渊」，进无咎也。</p><p>「飞龙在天」，大人造也。</p><p>「亢龙有悔」，盈不可久也。</p><p>「用九」，天德不可为首也。</p><p>解读</p><p>「乾，元、亨、利、贞」者，乾，天也。天是体名，乾是用名。谓天体凝寂，非人所法，故圣人欲使人法天之用，不法天之体，故名之曰「乾」，而不名之曰天也。若「元、亨、利、贞」，此四者，亦是天之四德也。天以四时之气，春生，秋杀，冬寒，夏暑，有此四时之义，故名为天也。周氏云：元，始也，于时配春，言万物始生，得其元始之序，发育长养。亨，通也，于时配夏，夏以通畅，合其嘉美之道。利者，义也，于时配秋，秋以成实，得其利物之宜。贞者，正也，于时配冬，冬以物之终，纳干正之道。若以五行言之，元，木也；亨，火也；利，金也；贞，水也。土则资运四事，故不言之。若以人事，则元为仁，亨为礼，利为义，贞为信。不言智者，谓此四事，因智而用。故乾凿度云：「水土二行，兼智兼信」是也。</p><p>「初九，潜龙勿用」者，潜，隐也。龙者，变化之物，喻天之阳气。初九，建子之月，阳气始动于地中，既未萌芽，犹是潜伏。比圣人有龙德，时未可行，惟宜潜藏，韬光遁世，故言「勿用」。</p><p>九二，见龙在田，利见大人。此当建丑之月，阳气发见，文明显著，故言「在田」也。「利见大人」者，此以人事明之，犹似圣人道德渐显，为天下众庶之所利见。若夫子教于洙泗，人虚往实归，见者皆利，故称「大人」。</p><p>九三，君子终日乾乾，夕惕者厉，无咎者，若，如也；厉，危也。既居下卦之上，不可骄盈，入上卦之下，心怀犹豫，故曰「终日乾乾」。从昼至夕，常怀忧惕，若有危厉，如此戒惧，乃得「无咎」。先儒云：若文王反国，大厘政之日。</p><p>九四，或跃在渊，无咎。或，疑；跃，跳也。阳气渐盛，犹龙跃在乎渊。如圣人位渐尊高，欲进王位，心怀疑虑，未敢果决，相时而动，故得「无咎」。若武王观兵孟津，候时而进，合经常道，故「无咎」。</p><p>九五，飞龙在天，利见大人。如圣人有圣德而登盛位，为天下众庶利见，故云「利见大人」。夫龙之为物，在地则行，在渊则跃，在天则飞。</p><p>上九，亢龙有悔。亢，极也，骄也。以阳气盛极喻之。圣人久处君位，不能谦和自守，而为骄亢，故致悔恨。先儒云：但九五之位，亦有大圣而居者，亦有非大圣而居者。非大圣而居者，不能免其忧悔，犹如尧之末年，四凶在朝，是以有悔。</p><p>用九，见群龙，无首，吉者，用，总也，此九阳之德也。谓圣人用此九阳之德，不可骄盈为物头首，更在谦柔卑退，降情接下，如此乃吉，故曰「无首吉」也。</p><p>象曰：天行健，君子以自强不息。行者，运动之称；健者，强壮之名。所以乾称「健」者，以其运行不息，无时亏退。故宋衷云：「昼夜不懈，以健详其名。」余卦各当名，不假于详也。「君子以自强不息」者，凡言君子，圣贤之通呼。故尧舜一日万几，文王日昃不暇食，仲尼终夜不寝，颜子欲罢不能自已，盖是修德乾乾，无时休息也。</p>',28)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
